// Command reference, served in layers to keep the always-loaded tool surface small:
//   - SIGS: one short line per command (inside the art_draw description)
//   - art_help {topic | op}: full details, tips and a working example on demand
//   - errors: a failing command's usage + example is appended automatically
// Keep SIGS terse; put explanations in DETAILS.
import { PART_DOCS } from './model3d.js';
import { AUDIO_TOPICS } from './audio/docs.js';
import { PLANET_TOPICS } from './space/docs.js';

/** op -> [signature, short purpose]. Field names are exact; "?" = optional. */
export const SIGS = {
  // shapes
  grid: ['x?,y?,rows:[str],legend?,cpp?', 'paint from text rows (1 char = 1 px; "." keeps)'],
  pixels: ['points:[[x,y,color?]],color?', 'single pixels'],
  line: ['x1,y1,x2,y2|points,color,width?,pixel_perfect?', 'line/polyline'],
  curve: ['points:[3|4 pts],color,width?', 'bezier'],
  polygon: ['points,color?,outline?,fill?', 'polygon'],
  rect: ['x,y,w,h,color?,outline?,fill?,thickness?', 'rectangle'],
  ellipse: ['x,y,w,h,color?,outline?,fill?,thickness?', 'ellipse in a box'],
  fill: ['x,y,color,tolerance?,contiguous?', 'flood fill'],
  text: ['x,y,text,color,font?,scale?,align?,shadow?', 'pixel font'],
  // color
  replace: ['from,to,tolerance?,region', 'swap one color'],
  remap: ['map:{from:to},tolerance?,region', 'swap several colors (variants)'],
  gradient: ['colors,direction?,dither?,region', 'banded gradient'],
  adjust: ['hue?,saturation?,lightness?,jitter?,alpha?,region', 'HSL adjust'],
  quantize: ['colors?,dither?,alpha_threshold?,region', 'snap to palette'],
  // surfaces + form
  shade: ['colors:[dark..light],light?,of?,depth?,profile?,per_color?,region', 'AUTO form shading of drawn shapes (use instead of hand shading)'],
  cells: ['colors:[dark..light],gap_color?,size?,gap?,layout?,stretch?,seed?,region', 'tileable shaded stones/scales/cracks'],
  noise: ['colors,weights?,scale?,octaves?,despeckle?,seed?,region', 'tileable noise'],
  scatter: ['colors|color,density?|count,size?,seed?,region', 'random specks'],
  outline: ['color,mode?,of?,from_layer?,diagonal?,region', 'outline shapes'],
  bevel: ['light?,dark?,size?,region', 'block edge highlight/shadow'],
  // transform
  copy: ['x,y,w,h,to_x,to_y,from_canvas?,from_layer?,from_frame?,scale?,flip_x?,tint?,opacity?', 'copy/stamp (also across canvases/frames)'],
  flip: ['axis,region', 'flip'],
  rotate: ['turns|angle,expand?,region', 'rotate (90° steps or any angle)'],
  shift: ['dx,dy,wrap?,region', 'move pixels (wrap = fix seams)'],
  mirror: ['axis,source', 'mirror half'],
  clear: ['region?', 'erase'],
  // light + atmosphere
  light: ['x,y,radius,color,intensity?,mode?,steps?', 'point light'],
  fog: ['color,from?,to?,direction?,noise?,steps?,region', 'haze'],
  rays: ['x,y,angle,spread,count,width,color,alpha?', 'god rays'],
  glow: ['threshold?,radius?,intensity?,gain?,normalize?,wrap?', 'bloom'],
  blur: ['radius,region', 'blur'],
  vignette: ['strength?,radius?,color?', 'darken edges'],
  cast_shadow: ['from_layer,dx,dy,color,squash?,skew?,soft?', 'drop shadow from a layer'],
  // iso
  iso_box: ['at:[gx,gy,gz]|x,y,tile,origin,w|size_left/right,height,top,left?,right?,outline?,edge?,anchor?,inset?', 'iso block'],
  iso_tile: ['same as iso_box without height,color', 'iso floor diamond'],
};

const REGION = 'region = x?,y?,w?,h? (defaults to the whole canvas/frame).';

/** Detailed docs + example per op (shown by art_help op:<name> and on errors). */
export const DETAILS = {
  grid: { doc: 'Each char is a palette key or a legend entry. "." and " " leave pixels unchanged; legend {"_":"transparent"} erases. cpp:2 = two chars per pixel for multi-char palette keys ("s1"). Best tool for deliberate hand-placed detail (faces, icons, outlines).', ex: { op: 'grid', x: 4, y: 2, legend: { o: '#2a1a22', s: '#e8b090' }, rows: ['.oo.', 'osso', 'osso', '.oo.'] } },
  pixels: { doc: 'points may carry their own color: [x,y,"#f00"].', ex: { op: 'pixels', color: '#fff', points: [[3, 3], [4, 3, '#ff0']] } },
  line: { doc: 'brush: round|square. pixel_perfect:true removes L-shaped doubles (clean 1px lines). points:[[x,y],...] draws a polyline.', ex: { op: 'line', x1: 0, y1: 15, x2: 15, y2: 0, color: 'o', pixel_perfect: true } },
  curve: { doc: '3 points = quadratic, 4 = cubic bezier. Pixel-perfect. Use for hair, tails, round outlines.', ex: { op: 'curve', points: [[2, 12], [8, 0], [14, 12]], color: 'o' } },
  polygon: { doc: 'fill defaults to true; outline = border color.', ex: { op: 'polygon', points: [[8, 1], [15, 14], [1, 14]], color: 'g2', outline: 'o' } },
  rect: { doc: 'fill:false with color draws only the border.', ex: { op: 'rect', x: 2, y: 2, w: 12, h: 8, color: 'w2', outline: 'o' } },
  ellipse: { doc: 'Bounding box x,y,w,h. fill:false with color draws only the border; thickness = border width in px (like rect).', ex: { op: 'ellipse', x: 2, y: 2, w: 12, h: 12, color: 'r2', outline: 'o' } },
  fill: { doc: 'Flood fill on the target layer; contiguous:false replaces the color everywhere; diagonal:true spreads through corners.', ex: { op: 'fill', x: 8, y: 8, color: 'b2' } },
  text: { doc: 'Built-in pixel fonts, uppercase (A-Z 0-9 punctuation, \\n). font "3x5" (default, tiny), "5x7" (readable UI/labels) or "7x9" (titles). scale multiplies; align left|center|right around x; spacing, line_spacing in px.', ex: { op: 'text', x: 32, y: 4, text: 'HELLO', color: '#fff', align: 'center', shadow: '#000' } },
  replace: { doc: REGION, ex: { op: 'replace', from: '#ff0000', to: 'r2' } },
  remap: { doc: `Swap several colors at once (derive color variants of an asset). Errors listing the colors present if nothing matched (allow_none:true to skip). ${REGION}`, ex: { op: 'remap', map: { r1: 'b1', r2: 'b2', r3: 'b3' } } },
  gradient: { doc: `direction: vertical|horizontal|diagonal|diagonal-reverse|radial. dither: bayer (default)|noise|none (false = none). Banded to the given colors. radial reaches the last color on the region edge (corners filled with it). ${REGION}`, ex: { op: 'gradient', colors: ['#1a1030', '#4a2a60', '#c06070'], direction: 'vertical' } },
  adjust: { doc: `hue in degrees, saturation/lightness -1..1, jitter = random ±lightness per pixel, alpha = opacity change -1..1 (-0.3 = 30% more transparent; result clamped 0..1), set_alpha = absolute opacity 0..1. ${REGION}`, ex: { op: 'adjust', lightness: -0.1, hue: 10 } },
  quantize: { doc: `Snap pixels to colors (default: the palette). dither none|bayer, strength. alpha_threshold:0.5 makes alpha binary. Run after effects to keep a coherent palette. ${REGION}`, ex: { op: 'quantize', dither: 'bayer' } },
  shade: { doc: `Shades shapes you already drew (any flat color) from ONE light direction using a ramp dark->light: rounded volume from the shape outline, no pillow shading. of: which colors form the shape (default every painted pixel in the region). light: top-left (default)|top|top-right|left|right|bottom-left|bottom|bottom-right or degrees. profile: round (dome, default)|flat (bevelled edges + flat top, set depth px)|sharp. per_color:true shades each flat color as its own part (e.g. arm vs body). bias -0.3..0.3 shifts lighter/darker; contrast; dither:true; wrap:true for tileable textures; cleanup:0 keeps lone pixels. Workflow: block in flat silhouettes -> shade -> outline -> hand detail. ${REGION}`, ex: { op: 'shade', colors: ['r0', 'r1', 'r2', 'r3', 'r4'], of: 'r2', light: 'top-left' } },
  cells: { doc: `Fills the region with a tileable pattern of separately shaded cells: cobblestone (size 5, gap 1), scales (layout brick), bricks (layout brick, stretch 2, profile flat, depth 1), cracked earth (gap_color dark, size 8), gravel (size 3). variation = per-cell tone shift (steps), jitter 0..1, depth/profile/light like shade. ${REGION}`, ex: { op: 'cells', colors: ['s0', 's1', 's2', 's3'], gap_color: '#2e2c36', size: 5, seed: 3 } },
  noise: { doc: `Tileable value noise. weights = exact share of each color. scale = feature size px (1 = per-pixel). despeckle:1-2 absorbs lone pixels (flat cartoon surfaces). Prefer cells/shade for stone; noise is for subtle variation. "keep" in colors leaves those pixels unchanged (sparse noise). Under a mask, transparent colors do not erase (no holes in the masked art) unless erase:true. ${REGION}`, ex: { op: 'noise', colors: ['d1', 'd2', 'd3'], weights: [0.3, 0.5, 0.2], scale: 3, despeckle: 1 } },
  scatter: { doc: `Random specks/blobs of size px. ${REGION}`, ex: { op: 'scatter', colors: ['g3', 'g4'], density: 0.05, size: 1, seed: 2 } },
  outline: { doc: 'mode outer (around shapes, default)|inner (on the shape edge). of: only shapes of these colors (selective outline). from_layer: outline another layer\'s shapes onto this layer. diagonal:true = 8-connected. skip_existing:true = pixels already in the outline color count as outline, not shape, so re-running never doubles it to 2 px (only fills gaps); it is the default when the layer already has that exact color (pass skip_existing:false for a second ring). Region limits where it writes; honours mask. Use a dark hue-shifted color, not pure black.', ex: { op: 'outline', color: '#2a1a22' } },
  bevel: { doc: `Light top/left and dark bottom/right edge lines of size px (blocks, planks, buttons). ${REGION}`, ex: { op: 'bevel', light: 'w3', dark: 'w0' } },
  copy: { doc: 'Copy a block (from this layer, from_layer, from_frame or from_canvas = asset stamp). Order: scale/flip, then hue/saturation/lightness, then tint (multiply), then opacity. skip_transparent defaults true. Build animation frames from a base frame: copy from_frame then move parts.', ex: { op: 'copy', from_frame: 0, x: 0, y: 0, w: 32, h: 32, to_x: 0, to_y: 1 } },
  flip: { doc: `axis x|y. ${REGION}`, ex: { op: 'flip', axis: 'x' } },
  rotate: { doc: 'turns:1..3 = 90° steps (square region). angle:<deg> = any angle with pixel-art-safe rotsprite-style sampling (no new colors). Region defaults to the whole canvas; pivot cx,cy defaults to its centre. Without expand, pixels rotated past the region/frame edge are cut. expand:true = nothing is cut: the canvas (every frame) grows just enough to hold the rotated content (content shifts by the left/top growth) and the result may extend past the region.', ex: { op: 'rotate', angle: 30, x: 8, y: 8, w: 16, h: 16 } },
  shift: { doc: `Move pixels by dx,dy (wrap:true default wraps around: shift by half the size to see/fix tile seams in the middle). ${REGION}`, ex: { op: 'shift', dx: 8, dy: 8 } },
  mirror: { doc: 'Copy one half onto the other mirrored: axis x|y, source left|right|top|bottom. Symmetric sprites: draw the left half, mirror.', ex: { op: 'mirror', axis: 'x', source: 'left' } },
  clear: { doc: `No region = the whole layer (with frame: the whole frame). ${REGION} Honours mask.`, ex: { op: 'clear', x: 0, y: 0, w: 4, h: 4 } },
  light: { doc: 'mode add|screen|multiply|paint; falloff smooth|linear|sharp; radius_y for ellipses; steps bands (0 = smooth). Paints empty pixels too (on_empty:false = only painted ones). Put lights on their own layer with blend screen/add.', ex: { op: 'light', x: 40, y: 30, radius: 18, color: '#ffb060', intensity: 0.8, mode: 'add' } },
  fog: { doc: `direction vertical|up|horizontal|radial; from/to = alpha; noise 0..1 wisps. For big smooth fog use steps:0 then quantize dither bayer once (a few steps + bayer looks like a screen door). ${REGION}`, ex: { op: 'fog', color: '#8fa6c0', from: 0, to: 0.4, direction: 'up', noise: 0.4 } },
  rays: { doc: 'God rays from x,y: angle (deg, 90 = down), spread, count, width (deg), length, alpha. Draw on a layer with blend screen/add.', ex: { op: 'rays', x: 20, y: -10, angle: 60, spread: 30, count: 4, width: 6, color: '#ffe7a8', alpha: 0.4 } },
  glow: { doc: 'Bloom around pixels brighter than threshold. select: value (default, HSV max channel: saturated neon blooms too) | luma (perceived brightness, the previous default) | saturation. Tiny 1-2 px emitters need gain:3-6 or normalize:true. wrap:true for tiling textures. steps bands it.', ex: { op: 'glow', threshold: 0.7, radius: 2, gain: 3 } },
  blur: { doc: `Depth of field for far/near layers (passes:1 for lighter). ${REGION}`, ex: { op: 'blur', radius: 1 } },
  vignette: { doc: 'strength 0..1, radius 0..1 where darkening starts.', ex: { op: 'vignette', strength: 0.5 } },
  cast_shadow: { doc: 'Projects from_layer\'s shapes onto this layer: dx,dy offset, squash (0.3-0.6 = on the ground), skew, base_y (ground row, default lowest painted row), soft = blur px (banded).', ex: { op: 'cast_shadow', from_layer: 'hero', dx: 3, dy: 0, squash: 0.4, color: '#00000066', soft: 1 } },
  iso_box: { doc: '2:1 pixel iso. Position with at:[gx,gy,gz] + tile + origin:[ox,oy] (origin = top vertex of cell 0,0) or x,y bbox. w = tile width (multiple of 4) or size_left/size_right; tiles_x/tiles_y; height px. Faces auto-shade from top; outline/edge colors. anchor:"center" centres a smaller box on its cell; inset shrinks it; fractional at allowed. Draw back to front (increasing gx+gy). Texture faces afterwards with mask:<face color>.', ex: { op: 'iso_box', at: [1, 1, 0], tile: 32, origin: [64, 20], height: 16, top: '#b89a72', outline: '#3a2a20' } },
  iso_tile: { doc: 'Flat iso diamond with the iso_box positioning; inset:1 leaves grout gaps.', ex: { op: 'iso_tile', at: [0, 0, 0], tile: 32, origin: [64, 20], color: '#6a7a5a', inset: 1 } },
};

export const COMMON = 'Every command may set: layer, frame (frame-local coords), mask ("opaque" | "transparent" | color | "!<color>" | "layer:<name>" | "!layer:<name>"), blend ("replace" | "over"), symmetry ("x"|"y"|"xy").';

/** art_draw description: compact signatures grouped by purpose. */
export function drawDescription() {
  const groups = [
    ['SHAPES', ['grid', 'pixels', 'line', 'curve', 'polygon', 'rect', 'ellipse', 'fill', 'text']],
    ['FORM/SURFACE', ['shade', 'cells', 'noise', 'scatter', 'outline', 'bevel']],
    ['COLOR', ['replace', 'remap', 'gradient', 'adjust', 'quantize']],
    ['TRANSFORM', ['copy', 'flip', 'rotate', 'shift', 'mirror', 'clear']],
    ['LIGHT', ['light', 'fog', 'rays', 'glow', 'blur', 'vignette', 'cast_shadow']],
    ['ISO', ['iso_box', 'iso_tile']],
  ];
  const lines = groups.map(([g, ops]) => `${g}: ` + ops.map((o) => `${o}{${SIGS[o][0]}}`).join(' '));
  return [
    'Run drawing commands on a canvas as ONE atomic undo step. commands: [{"op":"rect","x":0,"y":0,"w":4,"h":4,"color":"#c33"}, ...] (each name{fields} below is {"op":"name", fields}). Pixels, origin top-left. Colors: #rgb #rrggbb #rrggbbaa, rgb(), hsl(), "transparent" or a palette key.',
    COMMON,
    ...lines,
    'region = x?,y?,w?,h?. art_help {op:"<name>"} = full options + example; errors include usage.',
  ].join('\n');
}

/** Usage text for one op (errors + art_help). */
export function opUsage(op) {
  const s = SIGS[op], d = DETAILS[op];
  if (!s) return null;
  return `${op} {${s[0]}} — ${s[1]}.${d ? ' ' + d.doc + '\nexample: ' + JSON.stringify(d.ex) : ''}`;
}

/** Topics for art_help. Short, task-oriented guidance (skills reference these). */
export const TOPICS = {
  workflow: `GOOD PIXEL ART, STEP BY STEP
1. Palette first: art_palette ramp per material (4-5 shades, hue-shifted: cool shadows, warm highlights). Few colors total.
2. Block in flat silhouettes (rect/ellipse/polygon/grid) in one mid color per part.
3. Form: shade {colors:[ramp], of:<part color>} per part (or per_color:true) — one light direction (top-left).
4. Outline: outline {color:<dark hue-shifted>} (outer). Optionally inner lines with grid.
5. Detail by hand (grid rows): eyes, highlights, texture marks. 1px details only where they read.
6. Check: art_critique (numbers + coordinates), then art_view. Fix, repeat. Finish with quantize if effects were used.
Avoid: pillow shading (light on every edge), noise/speckle everywhere, pure black outlines, too many colors, isolated stray pixels.`,
  textures: `TILEABLE TEXTURES (blocks, floors, walls)
- Stone/cobble/scales/bricks/gravel: cells (one command) with a 3-5 shade ramp + gap_color; then a few hand details.
- Organic (dirt, sand, grass top): base fill, noise scale 2-4 despeckle:1 with 3 shades, scatter a few highlight specks.
- Wood planks: rect bands, bevel per plank, line grain, a knot with ellipse.
- Metal/gems: rect/polygon facets in a flat color, shade profile:flat depth 2-3, bright 1px highlight, outline.
- Always: art_view tile:3 or art_critique (tiling_seam). Fix seams: shift dx,dy = half size (wrap), repair the middle cross, shift back.
- Variants (colors/dyes): duplicate canvas + remap the ramp.`,
  characters: `CHARACTERS & SPRITES
- Pick a frame size and keep it (16, 24, 32, 48). Ground line = same row in every frame; leave 1px margin.
- Proportions are a style choice (chibi big head, heroic, realistic, monstrous); keep them identical between frames. Readable silhouette, 1px dark outline.
- Draw on layers per part (body, head, arms, gear) so parts can be shaded (shade per_color) and moved per frame.
- Directions/turnarounds + animations stay consistent with art_rig (parts + poses → generated frames). See art_help topic:"rig".
- Without a rig: draw frame 0, then copy from_frame 0 into the next frame and only move/redraw the parts that change.
- Check animation with art_critique (volume_drift, ground_line, palette_drift) and art_animation filmstrip.`,
  animation: `ANIMATION
- A canvas with frames = vertical strip of equal frames. art_animation: insert/duplicate/move/delete frames; tag {name, from,to, duration|durations|fps, loop, direction}.
- Key poses first, then in-betweens. Walk: contact, down, passing, up (x2 for left/right). Idle: 2-4 frames, 1px breathing bob. Attack: anticipation, smear, impact, recovery.
- High frame rates (12-24 fps): use art_rig — poses on keyframes, tween generates the in-betweens with sub-pixel-safe rotation.
- Draw a frame: art_draw {frame:N}. Check: art_view {frame, onion:1}, art_animation filmstrip, art_critique.
- Export: art_animation export format gif (preview) | spritesheet (png + Aseprite-style json) | frames. path "out/knight" writes out/knight.png+.json (json:false = png only); a folder path ("out/knight/") writes out/knight/<canvas>.*.`,
  scenes: `2.5D / HD-2D SCENES
Layers back to front: sky, far, mid, play, foreground. Far = lower contrast, bluer; optional blur. Lights on their own layers (art_layer add blend:"screen"/"add"), shadows blend "multiply", color grade "overlay". fog between depth layers, rays from windows/canopies, glow on emissive pixels. Finish: art_layer stamp_visible + quantize the stamp. Stamp repeated props with copy from_canvas (scaled/tinted for distance). Iso: iso_box/iso_tile back to front. art_canvas normal_map for engine lighting.`,
  hires: `HIGH-RESOLUTION PIXEL ART (128px .. 2048px)
- Work in regions: art_view x,y,w,h zooms (a big canvas view is downsampled overview), art_read only small regions.
- Block in with shapes + shade (geometry based, resolution independent), cells/noise for surfaces, then detail per region.
- Upscale a small sketch: art_canvas scale {factor, method:"scale2x"} keeps clean pixel edges, then refine.
- Use layers per depth/part; effects (light/fog/glow) scale well.`,
  minecraft: `MINECRAFT RESOURCE PACKS
Blocks/items 16x16 (Java). Names differ by version: 1.12 textures/blocks + textures/items (planks_oak), 1.13+ block/ + item/ (oak_planks). art_minecraft vanilla lists real names/sizes (references only, never ship vanilla art). Set canvas meta.texture (e.g. "blocks/stone"); art_minecraft build {project} writes the pack + zip. Animated textures = frames. Grass/leaves are grayscale + biome tint (meta.tint for previews).`,
  rig: `RIGS: CONSISTENT MULTI-VIEW, MULTI-ANIMATION ASSETS (art_rig)
Coordinates: root = where the root part's pivot sits in the frame; a child's "at" = offset of its pivot from the PARENT'S PIVOT (not its corner), so a head on a body with pivot at the body's bottom needs at:[0,-bodyHeight].
A rig = parts (drawn ONCE per view on the "<name>_parts" canvas), joints (pivot + parent + rest offset "at"), and poses (per-part x,y offsets px, rot degrees, sx/sy scale for squash & stretch, variant, hide). Every generated frame is assembled from the same part pixels, so the character stays identical across directions and animations, and in-betweens are tweened at any fps.
0. Quick start: create {name, frame:[32,32], template:"humanoid"|"blob"|"flyer"} gives parts, views, poses and presets (humanoid: idle, blink, walk, run, attack, hurt, jump, death; blob: idle, hop, blink, hurt, death; flyer: fly, hurt, death). Templates are only starting points: in the same create pass parts:{head:{w:14,h:10}, tail:{w,h,pivot,parent:"body",at,z}, arm_b:null}, views, root, poses or presets to change anything; later art_rig update / pose. Then draw the cells and animate {preset:"walk", view:"side"} (any preset field can be overridden, e.g. frames:16, fps:20).
1. Custom: create {name, frame:[w,h], views:["side","front","back"], mirror:{side_left:"side"}, root:[x,y] (where the root part's pivot sits in a frame), parts:{body:{w,h,pivot:[x,y]}, head:{w,h,pivot,parent:"body",at:[dx,dy],z}, arm_f:{..., views:{front:{at:[..],z}, back:{hidden:true}}}, eyes:{..., variants:["closed"]}}}. The reply lists every cell [x,y,w,h] per view; the visible "cells" guide layer marks cells (blue) and pivots (red) and never reaches frames.
2. Draw each part in its cell (flat colors -> shade -> outline), same palette keys in every view. Pivot = the joint (top of a limb, bottom of the neck).
3. pose {pose:"contact", parts:{leg_f:{rot:-30}, leg_b:{rot:30}, arm_f:{rot:25}}} — offsets from the rest pose; from:"<pose>" copies one as a base. Poses work in every view.
4. animate {animation:"walk_side", view:"side", keys:[{pose:"contact"},{pose:"pass"},{pose:"contact",mirror_pairs:true},{pose:"pass"}], frames:12, fps:12, plant_feet:true} -> frames + tag on canvas <name> (or canvas). mirror_pairs swaps *_f/*_b, *_l/*_r parts (second half of a walk). keys may set t (0..1) and ease (smooth|linear|step).
4b. One canvas holds everything: every animate call (default canvas = rig name) appends its frames under its own tag. Preset tags are always <preset>_<view> (walk_side, walk_front, idle_side, ...); animation:<name> picks your own. turnaround {pose?, views?} = one frame per view (tags = view names) for a still front/side/back sheet.
4c. Game-engine extras: every animate saves per-frame anchors (each part's pivot x,y,rot) and spritesheet json frames[].anchors carries them (attach weapons, hats, backpacks, particles). Paper-doll layers: animate the same keys with hide:["head"] (body layer) and only:["head"] (head layer) into different canvases: identical timing and ground shift, so they stack exactly and the head can be swapped in-engine.
5. preview {pose} shows all views side by side with the ground line; art_critique {canvas, animation} checks drift. update {parts:{...}, presets:{...}} resizes/adds parts (keeps drawn pixels) and saves reusable animations.
HIGH-DETAIL CHARACTERS (late-90s pre-rendered / "Replaced" look, 64x96 .. 160x240 frames):
6. create {name, frame:[128,192], template:"humanoid_hd"}: pelvis (root), torso, chest, neck, head(+blink), upper_arm/forearm/hand _f/_b, thigh/shin/foot _f/_b, plus optional slots weapon (child of hand_f), gear_back, gear_hip, cape. Views side, front_side (3/4), front, back_side (3/4), back + mirrors side_left, front_side_left, back_side_left = 8 directions. Presets: idle 12f, blink, walk 16f, run 12f, crouch_walk 16f, aim 1f, shoot 6f, reload 24f, hurt 8f, death 20f, throw 12f (IK, foot planting, cape follow-through on). Elbows/knees bend because limbs are parent chains. Leave unused slots empty or remove them with null.
7. Per-view poses: a pose may hold views:{front:{thigh_f:{rot:0, sy:0.8}}} merged over the base pose in that view (mirror views use their source view); tweening blends them. pose {pose, parts, views}. Side-view rotations splay sideways in front/back: override them there (humanoid_hd presets already do: forward swings become sy foreshortening).
8. IK (two-bone, solved per frame after FK, in each view): pose or key ik:{hand_b:{target:{part:"weapon", at:[14,-2]}, bend:-1}, hand_f:{target:[70,60], rot:0}} rotates the end's parent + grandparent so the end pivot reaches the target. target = frame px of the drawn view, or {part, at:[dx,dy]} in that part's rotated frame (a grip, a holster). bend 1 = joint toward +x when the limb hangs (knees in side view), -1 = elbows. rot = world rotation of the end afterwards (keep a gun level). A key without the entry fades back to FK. plane:"depth" bends toward the camera (front/back views, needs scale_children).
9. animate {..., plant:true} (alias ik_feet) pins stance feet: frames whose ankle is within ~2% of the frame height of the rest ground are contact frames; the ankle sits on the ground row and slides at constant speed through each contact (a standing foot stays put), solved with leg IK. plant:["foot_f"] picks parts; rig "feet" sets the default (auto: parts named foot* with a two-bone chain).
10. Secondary motion: rig secondary:{cape:{stiffness:0..1, damping:0..1, gravity?, inertia?}}; animate {secondary:true} (or an inline map) runs a damped angular spring driven by the parent's motion, so capes, scarves, straps and pouches lag and follow through. Loops are simulated until the seam repeats, so loops stay seamless.
11. Rig options: sampling:"rotsprite" (3x3 supersampling of the 8x Scale2x cell + majority colour + hole/stray cleanup: stable limb thickness, only existing colours; humanoid_hd default) | "smooth" (same on the 1x cell) | "nearest8" (old rigs' default). scale_children:true makes a part's sx/sy also move its children's joints (foreshortening, breathing). Frames per canvas are limited to 8192 px of height: at 128x192 that is 42 frames, so give each preset+view its own canvas (canvas:"hero_walk_side").
12. Export: art_animation export {format:"spritesheet", json:false} skips the sidecar json.
13. Equipment sets: give parts variants (chest:["plate"], head:["helmet","helmet_blink"]) and optionally rig variant_sets:{heavy:{chest:"plate", head:"helmet"}}; animate {..., variant:"heavy"} (or ["heavy","medium"]) renders every part with that set: no per-set sheet swapping. A pose variant (blink) combines as <set>_<variant> (helmet_blink) when the part has it.
14. Replies: create / update / info answer with a summary (cells as rows:{view:y} + parts:{part:[x,w,h]}, so a cell = [x, rows[view], w, h]; poses as names; presets as frames/fps). full:true = the complete JSON; fields:["poses"] = just those fields in full. art_info is a summary too (full:true for palette, meta, frame lists).
HELD WEAPONS (weapon handling, opt-in): create {..., template:"humanoid_hd", weapon:{class:"rifle"|"carbine"|"smg"|"shotgun"|"dmr"|"sniper"|"lmg"|"pistol", attachments?:{vgrip:"vertical_grip"|"angled_grip"|"bipod"|"suppressor"|"optic"|"light"}}} (or update {weapon}). Draw the weapon (and att_<name> cells) in the side row only, pointing RIGHT: the solver projects that cell into every view.
- Points (weapon cell px; defaults are fractions of the cell): points:{grip_main:{at:[x,y], angle}, grip_support:{at, angle, slide?}, stock, muzzle, optic, mag}, sockets:{underbarrel, top, muzzle}. An attachment mounts its cell pivot on its socket and may take over grip_support (vertical/angled grip, bipod), muzzle (suppressor) or optic. attach:[names] = the active ones (animate attach:[...] per call).
- Carry states (long guns): aim (stock in the shoulder pocket, cheek weld to the optic line), ready_low, ready_high, hip, sprint, reload (support hand free for the pouch / magazine), slung, one_hand_low, drop, holster (hidden). Pistols: aim (isosceles, optic at eye height), compressed, low, reload, one_hand_low, holster. A pose or key sets carry:"aim"; weapon.poses maps pose names to states (the humanoid_hd presets come mapped: run = sprint, throw = slung, reload = reload, death drops it); weapon.carry = the default; animate carry:"ready_high" overrides every frame; weapon.states:{name:{base:"hip", at:[fwd, down] (arm lengths from the shoulder), angle (deg, + = muzzle down), lateral, lock:["main","support"], fire?}} adds your own.
- Every frame of every pose and clip: the weapon is placed per state in a 3D body proxy, then both hands lock onto their grips with two-bone IK and wrist rotation; a pistol's support hand cups the trigger hand. Reach uses the rig's arm lengths: the shoulders protract a little, the support hand slides back along a rail, then the weapon moves back along its axis; limbs never stretch and elbows bend down / out. The torso, head and legs (and free arms) are capsules the weapon may not enter (weapon.standoff = minimum chest-to-receiver gap): it is pushed forward first, then outward, turning about the stock when shouldered. Muzzle discipline: outside firing states the muzzle points down / forward-low and never at the own body. Front / back views: a barrel pointing at the camera is canted outward with a length floor (weapon.foreshorten:{floor:0.42, cant:16, back_cant:45} | false).
- Draw order: the weapon goes over the torso when held in front of it and under it when behind (depth from the 3D proxy); weapon.layer:{above:[parts], below:[parts], pin:{<view>|all:"front"|"back"|z}} overrides. layers {name, pose|preset+frame, view} lists the stack with the reason for each z; explain {part_a, part_b, ...} says why one is over the other.
- mirror_pairs swaps legs and free arms but keeps held hands (and the weapon) on their side; key mirror_hands:true swaps the hands on purpose (the weapon moves to the other shoulder).
- check {name, clips?, views?, detail?} runs every frame of every preset in all 8 directions: hand-to-grip distance, arm over-extension, inverted elbows, weapon-body penetration, muzzle flags, layering and weapon visibility (back-facing views only need the muzzle to show) -> pass/fail + the failing frames. animate validates the same way: constraints:"refuse" (default: nothing written), "fix" (auto-correct: muzzle down, stronger cant, flipped elbows, draw order), "warn" or "off". Pose IK targets may name weapon points: ik:{hand_b:{target:{weapon:"mag", at:[0,4]}}} (points: stock, grip_main, grip_support, muzzle, optic, mag, charge).
- Aimed at the camera (front views, firing states) the barrel stays short and is canted INWARD (muzzle toward the centre line; foreshorten.aim_floor 0.24, aim_cant 9), drawn over the forearms and the trigger hand and under the support hand (a pistol's slide over both hands), and the head tilts onto the stock (weld_tilt 10). A shouldered aim seen from behind keeps a longer barrel (foreshorten.back_floor 0.55) so the muzzle clears the torso. humanoid_hd with a weapon adds a "mag" part (draw it in the side row; it rides in the mag well) and "mag_hand" (art:"mag": the same cell in the support hand); the reload preset is grab -> strip (mag in hand) -> chest pouch -> seat -> charging handle (state reload_charge) with events mag_out, mag_pouch, mag_in, charge, ready.
DEPTH, DRAW ORDER, LINKED CELLS (2D rotated sprites):
- depth:true (rig option; library skeletons default to it): each arm chain hanging from the chest goes over the chest when it is in front of the chest's front surface, under it behind its back surface, authored order in between; decided per frame with hysteresis in clips (no flicker). depth:{rules:[{part:"upper_arm_b", ref:"chest", chain?:true, split?:true, views?}], margin?, thickness?:{chest:[deep, wide]}}. split: a bone crossing the surface is cut into a pivot piece and a tip piece with their own z.
- z keyframes: a key {pose, z:{forearm_b:9}} sets draw order for that key (steps at the tween midpoint); a pose z wins over the depth model.
- zcheck {name, clips?, views?, window?} -> z-flicker (two overlapping parts swap order and swap back within window frames) and depth violations, with each failing frame's order. layers {name, tag | all_frames:true} gives every frame's stack with the rule per part and debug_render {name, tag|preset, frame} a per-part atlas (the web UI's Layers view uses both). animate stores per-frame draw order (bottom -> top) in meta.order when depth is on (order:true otherwise); spritesheet json frames[].order / frames[].events.
- Linked cells: parts.p.link:{back_side:"side"} or views.<v>.link:{view, flip?} draws another view's cell (no redraw); parts.p.art:"<part>" draws another part's cell (mag_hand); parts.p.hide:true = hidden until a pose sets hide:false. consistency {name, views?, tolerance?} compares the views of every part (empty cells, palette drift, bone length drift, pivot / joints off the drawing, rest silhouette height). derive {name, from:"side", to:["front_side"], parts?, flip?, overwrite?} copies cells as a start to paint over.
- stable:true (animate; batch default) quantizes each part's drawing angle (3 deg steps, hysteresis) so slow limbs do not shimmer; joints stay exact. events:[{t, name}] on animate / presets -> frames (meta.events).`,
};

TOPICS.library = `ANIMATION LIBRARY (art_anim): author motion once per skeleton, render any skin
1. skeleton {name:"hd", template:"humanoid_hd", frame:[128,192], weapon?:{class:"rifle"}, proportions?:{heavy:{width:1.15, spine:1.04}, lean:{width:0.9, legs:1.04}}} saves the rig definition (no art), masks (lower = pelvis + legs, upper, arms, head, all; masks:{} adds yours) and the clip library: the template presets plus walk_aim (walk legs + aim upper body: a layer with mask "upper"), flinch (additive upper-body hit) and walk_hit. depth:true is on by default. from_rig:<rig> or parts:{...} build one from your own rig.
2. clip {skeleton, name, keys:[{pose|parts, t?, ease?, carry?, z?}], frames, fps, loop?, events?:[{t, name}], plant?, secondary?, carry?} | {layers:[{clip:"walk"}, {clip:"aim", mask:"upper", weight?:1}, {clip:"flinch", additive:true}]}: a layer with a mask overrides those parts (blended by weight, IK ends included); an additive layer adds its offset from its first frame (or ref pose). A clip without keys starts from its first layer. delete:true removes it. from_rig + preset copies a rig preset.
3. skin {name:"mec", skeleton:"hd", proportions?:"heavy" | {...}, parts?, variant_sets?, equipment?:{helmet:{variant:"helmet"}, pack:{part:"gear_back"}}, loadouts?:{light:{equip:["helmet"]}, heavy:{set:"heavy", equip:["helmet","pack"]}}} creates the rig "mec" with the proportioned cells (draw them) or binds an existing rig (rig:<name>, map:{skeleton_part: rig_part}). Clips retarget to the skin's proportions automatically.
4. render {skin, clip, view, loadout?} -> a canvas like art_rig animate. retarget {clip, from, to, map?} copies a clip to another skeleton (named poses inlined, translations scaled by hip height, IK targets moved with the root; rotations unchanged).
5. batch {skins:["mec","sev"], clips?:[...] (default all), views?:"drawn"|"all"|[...], loadouts?:"all"|[...], out:"<assets dir>", manifest?:"manifest/characters.json", pad?:"auto" | n | [l,t,r,b], front?:"auto" | [parts], stable?:true, max_width?} writes characters/<set>/<clip>_<view>.png horizontal strips (+ <clip>_<view>__front.png: parts drawn over the weapon, or the near arm) and merges sprites.<set> = {frame, anchor (ground point), pad, skeleton, skin, loadout, class, anims:{<clip>_<view>: {file, front?, frames, fps, loop, events?, order?: [{frame, parts (bottom -> top)}] where it changes, grid? (wrapped at max_width)}}} into the manifest. pad:"auto" (default) grows the set's frame symmetrically to fit every frame (a rifle barrel in the side view) and records it: the engine anchors on "anchor".
6. gltf {skin, clips?, path?} exports a skinned cutout mesh (a quad per part from the base-view cells, one joint per part, bind = rest pose) with the clips as animations (scale 0 while a part is hidden; events in extras).
Paths: absolute, "./x" = the MCP server's working directory, bare relative = the workspace exports folder (the reply says where it went).`;

TOPICS['3d'] = `3D MODELS FROM PIXEL ART (art_model -> glTF .glb, HD-2D look)
Pixel textures on low-poly meshes, NEAREST filtering, alpha MASK (BLEND for opacity/glass parts). Units = art px; export divides by scale (32 px = 1 unit). Y-up, +Z = front. Each builder's origin is bottom-centre (floor: top-centre; extrude/lathe: canvas meta.pivot). Model origin:"auto" (default) keeps part coordinates so kit pieces snap to the grid; for a standalone prop, ship or vehicle set origin:"bottom" (bbox centred on X/Z, bottom on y=0) or "center". Z-up engines (Sanctum Burn / Three.js camera.up=Z): object.rotation.x = Math.PI/2, or export {up:"z"}.
WORKFLOW: 1. Paint tileable textures first (32x32 = one grid cell; art_help topic:"textures"). 2. One model per kit piece: art_model create {name, parts:[...]}. 3. art_model preview {name} (game = 38° pitch perspective like the game camera, plus front/side/top/iso; views:["game"], size:512 for a big diorama look). 4. update {set:{0:{h:96}}} / add / remove and re-preview. 5. export {name} -> exports/<name>.glb + <name>.meta.json (bounds, triangles, units).
PARTS (every part: at:[x,y,z] px, cell:[gx,gy,gz] = x grid (32), turn:0-3 = 90° about y, rotate:[x,y,z] deg, scale, pivot:[x,y,z], mirror, array:{count, step:[x,y,z] | cell_step:[1,0,0], turn?, rotate?, about?}, opacity, glass, double_sided, hidden):
TRANSFORM ORDER: scale, then rotate X then Y then Z (fixed axes, degrees), then turn, all about the part's own origin (local 0,0,0) or about pivot:[x,y,z] (local px, e.g. a door hinge or a wing root); then at + cell*grid. mirror:"x"|"y"|"z" (or a list = every combination) also emits the copy mirrored across the model's x=0 / y=0 / z=0 plane, winding and normals fixed (image-mapped faces show the mirrored image). array copies: rotate/turn k steps about the copy's own origin, or with about:[x,y,z] (model px) about that point = radial array (engine rings, rotor blades, turret ports).
MATERIALS: opacity:0..1 (< 1 = glTF alphaMode BLEND, baseColorFactor alpha = opacity, texture alpha multiplies) and glass:true (BLEND, opacity 0.35 unless set, doubleSided, low roughness) for canopies, cockpit domes, visors, force fields. double_sided:true = doubleSided material. Translucent materials keep their own material (not atlased); engines draw them after opaque meshes without depth writes (material extras depthWrite:false), the preview blends them the same way.
${Object.entries(PART_DOCS).map(([k, v]) => `- ${k} {${v}}`).join('\n')}
TEXTURES: texture = canvas name | "#rrggbb" | {canvas, frame?, layer?, region:[x,y,w,h], overlay:<grime canvas>}. Per face: faces:{top,bottom,front,back,left,right} or the same keys on the part; side = every vertical face; cap = top+bottom. Kit pieces get WORLD UVs after placement (1 texel = 1 px, planar per face direction, lattice origin at the grid cell edge): any offset, turn, array or nested layout continues the texture across touching pieces and courses run on around corners; tile:false fits one copy per face. three.js runtime version of the same mapping: README "World-space UVs". Emissive = a layer named "emissive" (or canvas <name>_emissive). export normal_maps:true makes/uses <canvas>_n.
RUINS: broken:true | {amount px, step px, seed} = jagged top (walls/arches) or eroded edges (floors). holes:<mask canvas> = painted pixels of the mask (stretched over the face) are cut out (cracks, breaches). Outlines are smooth polygons (marching squares + simplify; res = sampling px, default 1); style:"voxel" (arch: voxel:true) gives the old blocky look. Arch curves get segments from their size.
OVERLAYS (grime, decay, moss, blood, wear) = alpha-cut decal shells with their own UV set (glTF TEXCOORD_1, strength in COLOR_0 alpha): overlays:[{texture:"grime", where:"bottom"|"top"|"corners"|"edges"|"all" (or a list), falloff:24 px, amount:1, jitter:0.5, map:"world" (own scale, scale:1) | "face" | "piece" | "surface" (stretched 0..1), seed}] on a part or on the model (all parts). Gradients use the whole continuous surface, not one piece.
CTM (connected textures, OptiFine/Continuity style): art_model ctm {name:"marble_ctm", ctm:{base:"marble", method:"full", border:{width:2, style:"bevel"|"line", color?}}} makes a tileset canvas; texture:"marble_ctm" on floors/walls then picks a tile per world cell from its 8 neighbours across ALL pieces (same plane + same connect key: material | texture | tag via ctm_tag; walls fold around vertical corners). Methods: full (47 blob), compact (5 tiles, quarters), horizontal, vertical, horizontal+vertical, top, random (weights, variants:[canvases] or auto flips), repeat (base = cols x rows cells, one big pattern), overlay (creep tiles from overlay:<canvas>; used as overlays:[{texture:"moss_ctm", from:"grass"}]). Hand-drawn: template:<canvas> with all tiles, or the 5 compact tiles (none, all, horizontal, vertical, inner corners) -> 47. Export writes <name>.ctm.json + tileset PNGs for runtime re-tiling (ctmTileFor in README). rubble {count, size, seed} scatters chunks.
LAYOUTS / DIORAMAS: a model whose parts are {type:"model", model:"wall_a", cell:[2,0,0], turn:1}. export bakes it into one mesh (fewest draw calls), or export {instances:true} = one shared mesh per kit piece + one node per placement. atlas:true packs small image-mapped textures (and colours) into one material.
RECIPES:
- Gothic arch kit: arch {texture:"stone", span:24, point:1, spring:20, d:8} (style:"solid" = door/window panel; style:"ring" = rib); vault {texture:"stone", span:64, d:32}; pillar/column between arches at cell edges; broken:{seed:3} for the ruined variant.
- Floor + walls: floor {texture:"tile", array:{count:4, cell_step:[1,0,0]}}; wall {texture:"brick", at:[0,0,-12], top:"cap_stone"}; corner for room corners; ledge/balustrade along edges; stairs {steps:4, rise:8, run:8, tread:"tile"}.
- HD-2D prop: extrude {canvas:"barrel", depth:6} (front/back = the sprite, sides = edge pixel colours).
- Gargoyle / carved relief: draw the gargoyle + a grayscale height canvas (light = thick), extrude {canvas:"gargoyle", depth_map:"gargoyle_h", depth:8, levels:4}.
- Lathed candle / urn / baluster / bell: draw the RIGHT HALF of the silhouette from x=0 (axis) on a canvas, lathe {canvas:"candle", segments:12}; flame pixels on an "emissive" layer glow.
- Chain: extrude a link sprite and alternate it: {type:"extrude", canvas:"link", depth:2, array:{count:6, step:[0,-6,0], rotate:[0,90,0]}}.
- Marble floor groups: ctm {name:"marble_ctm", ctm:{base:"marble", method:"full", border:{width:2}}}; floors {texture:"marble_ctm", cell:[..]}: one bevelled border around each connected group, none on the seams. Separate rooms: ctm_tag:"hall" vs "chapel" with ctm:{connect:"tag"}.
- Gothic stone walls: wall {texture:"stone"} runs at any offset (world UVs keep the bricks continuous); base trim = ctm {name:"trim_h", ctm:{base:"trim", method:"horizontal"}} on a ledge row (end caps only where the run stops); random {weights:[6,1,1]} for occasional cracked blocks.
- Spaceship hull: loft {points:[[-12,0],[12,0],[10,10],[-10,10]], d:64, scale_end:[0.3,0.4]} (narrows toward the +z nose), wings = wedge {w:40, h:3, d:24, top_w:8, shift:[16,0], at:[14,2,0], mirror:"x"}, nose cone {type:"cone", r:6, h:12, rotate:[90,0,0], at:[0,5,32]}, engines = cylinder {r_bottom:5, r_top:4, h:10, rotate:[-90,0,0], at:[10,5,-32], mirror:"x"}, canopy box {w:10, h:6, d:14, bevel:2, glass:true, color:"#9fd8ff", at:[0,10,12]}, intakes/hatches = box insets:[{face:"front", rect:[4,2,8,4], depth:3}] (recess) or depth:-1 (raised panel), hangar mouth = an inset touching the bottom edge. Side profile of a fuselage: shape {plane:"zy", points:[[z,y],...], d:<width>}. Export with origin:"bottom".
- Radial engine ring: cylinder {r:3, h:6, at:[16,0,0], array:{count:6, rotate:[0,60,0], about:[0,0,0]}}. Hinged door: box {w:16, h:24, d:2, rotate:[0,-70,0], pivot:[-8,0,0]}. Decal on a fuel tank: cylinder {side:"tank_decal", wrap:"once", u_offset:0.25} (image centre faces +x; u_offset in turns), wrap:"repeat" (repeat:n) = seamless repeats.
- Moss + grime: overlays:[{texture:"grime", where:["bottom","corners"], falloff:20}, {texture:"moss", where:"top", falloff:10}, {texture:"wear", where:"edges", falloff:3}].
Keep it light: kit pieces < 500 tris, few textures shared by many pieces.
HARD-SURFACE DETAIL (ships, stations, carrier interiors, cities at a pixel-texture budget):
- PBR: part material:"painted_metal"|"bare_metal"|"rubber"|"plastic"|"glass"|"emissive_panel"|"fabric" or {metal:0..1, rough:0..1, preset?} -> glTF metallicFactor / roughnessFactor (default stays metal 0, rough 1). Canvas-wide: art_canvas meta {material:"bare_metal"}. Per texel: layers named "metal" and "rough" on the texture canvas (grey = value, unpainted = the factor) -> metallicRoughnessTexture (G rough, B metal), never part of the colour. glass = the glass:true material; emissive_panel glows with its own colour when the canvas has no emissive layer. atlas:true merges PBR textures into one metallicRoughness atlas.
- Height + normals: a layer named "height" (white = high) makes a pixel-correct normal map: no blur, only texels within bevel texels of a drop to a lower neighbour tilt (the high side gets the chamfer), tiles wrap seamlessly; glTF convention (green = up). bump:<strength> | {strength:1 (texels of height per full step, 1 = 45° rims), bevel:1..8, auto:"luminance"|"panels" (derive height from brightness steps or from dark panel lines when there is no height source), levels, threshold, invert} on a part, on the canvas meta, or export/preview {bump} for every canvas with a height source (height layer or a same-size <canvas>_h canvas). The preview lights normal maps, metalness and roughness per pixel.
- Greebles: {type:"greeble", w:96, d:64, seed:3, density:0.45, size:[3,12], height:[1,4], kinds:["panel","vent","pipe","conduit","antenna","bolts","hatch","heatsink","nozzle","dome","cables","tank","block"] | {vent:3, pipe:1}, grid:4 (snap to the panel grid), align:"grid"|"free", gap:1, margin:1, avoid:<mask canvas> | [[u,v,w,h]], texture, dark, accent, textures:{vent:"..."}, drop_lod:"auto" (pieces <= 2 px tall drop at LOD 1, taller at LOD 2) | n, instanced:false} scatters non-overlapping pieces on the y = 0 plane facing +y (seeded: same seed = same pieces). On box / wall / floor / slab / ledge: greebles:[{face:"top"|"front"|..., ...}] scatters over that face (top-left as seen from outside, like insets). Your own pieces: kinds:["model:my_vent"] or create a model with greeble_kind:"my_vent" and use kinds:["my_vent"] (fitted to the footprint). Pieces merge into the model mesh (same materials = same draw calls); instanced:true exports one mesh per distinct piece + EXT_mesh_gpu_instancing nodes (three.js GLTFLoader -> InstancedMesh). LOD export drops greebles from drop_lod on.
- Sweeps: {type:"tube"|"sweep", path:[[x,y,z],...], curve:"linear"|"catmull"|"bezier" (3n+1 points), segments:6, r:2, r_end?, sides:8, profile?:[[x,y],...] (custom section: x side, y up; rectangles = conduits / rails), twist?, caps:true|"start"|"end"|false, closed?, up?, texture (u around, wrap:n; v = world px along) | trim:"sheet:strip"}. Hanging cable: {type:"tube", from:[x,y,z], to:[x,y,z], sag:10, r:0.5, sides:4}. Polyline corners are mitred, frames never flip.
- Trim sheets: art_model trim {canvas:"hull_trim"} paints a 64-wide sci-fi sheet (strips plate, bevel, bolts, seam, hazard, grate, rib, pipe, rubber, light, plate_dark with height, metal, rough and emissive layers; strips:[{name, style, h, base?, accent?, glow?}], colors:{base, light, dark, accent, glow}); art_model trim {canvas:"my_sheet", strips:{edge:[0,8], seam:[8,4]}} marks a hand-painted one ([y, h] rows). Parts: trim:"hull_trim:bevel" | {sheet, strip, faces:"auto"|"edges"|"all", scale, flip, max}: auto = bevel chamfers + inset walls + faces thinner than the strip; u runs along the face at world scale (seamless along a run), v spans the strip. Tubes map the strip around the section. Ship hulls and interiors share one texture.
- Mesh ops: boolean:"subtract"|"union"|"intersect" on a part cuts / joins its target (target: part index, id:"name" or name; default the previous part); the cutter is not emitted; results stay closed and manifold (T-junctions split), world UVs continue on the cut walls; pieces away from the cutter (greebles) keep their triangles. Model merge:true | {weld:0.01, internal:true} welds near vertices and drops hidden faces between touching pieces. Model morphs:{open:{set:{door:{rotate:[0,-90,0]}}}, damaged:{model:"hull_damaged"}} (door = part index or id:"door"; a part name makes it a rig node, and rigs cannot morph yet) -> glTF morph targets (mesh.extras.targetNames, weights 0); a morph may move, turn or resize parts, not change segment counts; preview {morph:{open:1}}.
- Shadows: part cast_shadow:false / receive_shadow:false -> separate nodes with extras {cast_shadow, receive_shadow} (rig nodes carry their part's flags).
RENDER COST (export options; preview {ao, lod, morph} shows them):
- bake_ao:true | {mode:"texture" (AO lightmap: occlusionTexture + TEXCOORD_1, one NEAREST chart per face, texel:2 px) | "vertex" (COLOR_0) | "both", samples:24, distance:24 px, strength:1, levels?} ray-casts hemispheres against the model (BVH): contact shadows in crevices, under greebles, in insets. Deterministic (same input = same bytes). Each LOD level bakes against itself into one shared lightmap.
- lods:[1, 0.5, 0.2] (lod_mode:"nodes" (default: <name>_lods > <name>_LOD0..n, extras.distance) | "files" (<name>_lod1.glb, ...), lod_screen:{height:720, fov:70, px:1}): quadric edge collapse onto existing vertices that keeps every triangle's own UVs (flat regions stay pixel-exact), material borders and open borders, drops hidden faces between pieces, greebles from drop_lod, overlays from LOD 1. meta.lods.levels[i].distance = where that level's error falls under px screen pixels (three.js: lod.addLevel(node, node.userData.distance)).
- impostor:true | {layout:"octahedral" (grid:8, hemi; full:true = whole sphere) | "ring" (angles:8|16, pitch), size:64 px per cell}: <name>.impostor.png (albedo, unlit) + _n (world normal) + _d (depth) + .impostor.json (cells: rect, dir; encode formula; quad size; switch_distance) for far LOD billboards.
- collision:"hull" (convex hull, <= ~124 tris) | "boxes" | {type, max_boxes:16, cell, hull_points:64}; occluder:"boxes" (conservative: inside the surface) | "hull": nodes <name>_collision / <name>_occluder (extras {collision|occluder, visible:false}; boxes listed in meta for physics). Not counted in triangles.
- stats:true: meta.parts_stats per part (triangles, bounds in units, greebles, GPU instances); also written with lods / impostor / collision.
- cull:{rooms:[{name, min:[x,y,z], max:[x,y,z]} | {name, cells:[[gx,gy,gz],[gx,gy,gz]]}], portals?:[{rooms:[a,b], min, max}], depth:2} on a layout model (or export {cull}): one node room_<name> per room (+ room_outside), doorways found automatically where two room boxes touch (open samples on the shared wall), meta.cull {rooms, portals, pvs}. Engine: find the camera's room, draw it + pvs[room] (or walk portals through the frustum). Browser budget: hero ship sections 3-8k tris at LOD0, kit pieces < 1k, GPU-instance repeated greebles, impostors past a few hundred units.
HARD-SURFACE RECIPES:
- Hull greebling: box {w:96, h:24, d:64, texture:"hull", material:"painted_metal", bevel:2, trim:"hull_trim:bevel"} + box {w:96, h:24, d:64, greebles:[{face:"top", seed:3, grid:4, density:0.5, avoid:[[40,0,16,64]]}, {face:"right", seed:4, kinds:["vent","pipe","bolts"], size:[2,6]}]} (or a greeble part on a hull face), a hatch = box {boolean:"subtract", target:"hull"} + an inset panel; export {bake_ao:true, lods:[1,0.5,0.2]}.
- Carrier corridor module (one trim sheet): art_model trim {canvas:"corr_trim"}; floor {texture:"deck", trim:{sheet:"corr_trim", strip:"grate", faces:"all"}}; walls box {w:64, h:48, d:4, insets:[{face:"front", rect:[4,6,56,36], depth:1}], trim:"corr_trim:bevel"}; light strip box {h:2, trim:{sheet:"corr_trim", strip:"light", faces:"all"}}; pipe runs tube {path:[..], trim:"corr_trim:pipe"}; ribs = box {array:{count:4, step:[0,0,32]}, trim:"corr_trim:rib"}; export {bake_ao:true, collision:"boxes"}.
- Pipe run: tube {path:[[0,40,0],[0,40,64],[32,40,64],[32,8,64]], r:2, sides:8, trim:"hull_trim:pipe"} + clamps box {w:6, h:6, d:2, array:{count:3, step:[0,0,24]}} + a sagging cable tube {from:[0,44,0], to:[0,44,64], sag:6, r:0.6, sides:4}.
- City block LOD + impostor: a layout model of building models, export {lods:[1,0.5,0.15], impostor:{grid:8, size:64}, occluder:"boxes"}: LOD0 near, LOD1/2 by meta.lods distances, the impostor billboard past impostor.switch_distance, occluder boxes for occlusion culling.
RIGS & CLIPS (rigid parts, PSX / Half-Life 1 style, no skinning; also maps to Roblox: one MeshPart per node + Motor6D):
- name:"bolt" makes a part its own glTF node (own mesh); parent:"receiver" nests it (child transforms are local to the parent). pivot:[x,y,z] (part-local px) = the JOINT: the node origin, what poses rotate about. Unnamed parts merge into the root mesh, or into their named parent's mesh (parent:"receiver" on an unnamed grip). rig:{merge:false} = every part its own node (auto names type_i). create/info report rig.tree, nodes (joint px, triangles), sockets, poses, clips.
- sockets:{muzzle:{part:"barrel", at:[x,y,z] (model px, rest pose, same space as part at), look?:[0,0,-1]}, sight:{part:"optic", at, look}, grip_r, grip_l, mag_well} -> empty child nodes socket_<name> (local -Z = look; omit part to hang it on the model root). Games: put socket_sight on screen centre for ADS, spawn the muzzle flash at socket_muzzle, hands on socket_grip_r / socket_grip_l.
- pose {name, pose:"cant", parts:{receiver:{rot:[0,0,-20], at:[dx,dy,dz], scale?}}, base?:<pose>}: offsets from the rest pose per node. at = px in the PARENT's frame (a magazine at:[0,-8,0] drops out of its receiver even when the receiver is tilted); rot = degrees X then Y then Z in the node's rest frame, about its joint.
- animate {name, clip:"reload_empty", keys:[{t:0, pose:"rest"}, {t:0.65, parts:{magazine:{at:[0,-9,1]}}, ease:"smooth"}, ...], loop?, duration?, ease?, events?:[{t:0.65, name:"mag_out"}]}: t in seconds (strictly increasing); a key = pose and/or parts (parts override the pose per node). ease on a key = the motion INTO it: linear (default) | smooth | step; clip-level ease = the default for every key. loop with duration past the last key closes back on the first key. keys:null deletes a clip (pose {parts:null} deletes a pose). Export writes one glTF animation per clip: channels per moved node (translation / rotation quaternions / scale); all-linear -> LINEAR at the key times, all-step -> STEP, otherwise baked at 30 fps. Events go in the animation's extras.events (sounds, shell ejects). Rotations interpolate the short way (slerp): split turns over 180° with an extra key.
- preview {name, pose} (views:["side","fp"]) or {name, clip, frames:6, view:"side"|"fp"|"iso"|{pos,look,fov}} = contact sheet with the time under each frame: check a reload by eye. view "fp" = first-person camera at the model origin looking down -Z, 60° vertical fov.
- Props (doors, chests, turrets, levers): the same named parts + pivot + pose + clip, e.g. a lid {name:"lid", parent:"base", pivot:[0,0,-5]} and pose {parts:{lid:{rot:[-105,0,0]}}}; skill prop-rig.
- export meta.json rig.nodes = parent-space translation (units) + rotation per node: Roblox Motor6D Part0 = parent, Part1 = node, C0 = CFrame(translation) * rotation.
TEMPLATES (view space: origin = the eye, -Z forward, +Y up, 32 px = 1 m; override anything with textures:{..}, set:{<part name>:{..}}, add, remove:[names], poses/clips/sockets:{name: value|null}):
- template:"fp_arms": clavicle_r/l > upper_arm_r/l > forearm_r/l > hand_r/l > fingers_r/l (+ thumb_r/l), slots textures:{sleeve, cuff, glove}; poses rest, grip_rifle, grip_pistol (palms on the fp_rifle / fp_pistol grip sockets); clip idle_breathe.
- template:"fp_rifle": receiver > barrel, handguard, stock, magazine, bolt, charging_handle, optic, trigger; sockets muzzle, sight, grip_r, grip_l, mag_well; poses fire_kick, bolt_locked, reload_tilt; clips fire (bolt cycle), reload_tactical, reload_empty (magazine out + in, charging handle). Slots {metal, polymer, magazine, optic, lens}.
- template:"fp_pistol": frame > slide, barrel, magazine, trigger; same sockets; poses fire_kick, slide_locked, reload_tilt; clips fire (slide cycle), reload. Slots {metal, slide, polymer, magazine}.
FIRST-PERSON WEAPON EXAMPLE (true 3D, .glb):
1. art_model create {name:"ar", template:"fp_rifle", textures:{metal:"gun_metal", polymer:"gun_poly"}, set:{magazine:{h:5}}} (texture canvases are ordinary pixel art and must exist first; a slot also takes a colour).
2. art_model create {name:"arms", template:"fp_arms", textures:{sleeve:"sleeve_camo", glove:"glove"}}.
3. art_model pose {name:"ar", pose:"inspect", parts:{receiver:{rot:[0,25,-30], at:[-2,2,-2]}}}; animate {name:"ar", clip:"inspect", keys:[{t:0, pose:"rest"}, {t:0.6, pose:"inspect", ease:"smooth"}, {t:1.6, pose:"inspect"}, {t:2.2, pose:"rest", ease:"smooth"}]}.
4. preview {name:"ar", clip:"reload_empty", frames:8, view:"side"}; preview {name:"arms", pose:"grip_rifle", views:["fp","side"]}.
5. export {name:"ar"} and {name:"arms"}: parent both to the camera in-engine; play "reload_empty" on the gun and a matching arms clip; socket_sight on screen centre for ADS.
PRE-RENDERED SPRITES (the PS1 / Doom technique: build low-poly, render to pixel sprites; arms as a separate layer):
- render {name, canvas, pose? | clip?, frames? (or fps, default 15), angles?:[{yaw,pitch,roll}] | sweep:{yaw:[-20,20,5], pitch:[-10,10,5], roll?}, camera?:"fp" (default) | "side" | "front" | "iso" | "top" | "game" | {pos,look,fov}, size:[w,h], light?:{dir:[x,y,z], color, ambient}, outline?:"#1a1a1a", quantize?:{colors:16 | ["#hex",..] | palette:"project" (needs the model in a project), dither:true}, only?/hide?:[part names], animation? (tag; default the clip / pose name, or "angles"), zoom?, fov?, duration? (ms per frame), parts? (inline pose)}: one frame per clip sample (or per angle; sweeps are row-major: pitch rows x yaw columns, tag "angles"), nearest texels, no anti-aliasing, transparent background, tagged as an animation on the canvas. Angles rotate the model about its origin (pivot:[x,y,z] to change). The camera is fitted to the FULL model for every frame, so layers rendered with only/hide stack exactly. Size defaults to [64,64], max 1024; max 400 frames per render. Limitation: the fp camera (and close {pos} cameras) DROP triangles crossing the near plane instead of clipping them, so a part reaching behind the eye (a long stock, a shoulder) can vanish in some frames: shorten or move it forward, or render camera:"side".
- Anchors: every frame stores each socket's screen position and screen rotation (forward axis) in meta.anchors[animation][frame] = {socket_grip_r:[x, y, rot], socket_grip_l, socket_muzzle, socket_sight, socket_mag_well}; art_animation spritesheet json writes them per frame (frames[].anchors; json:false strips them).
- Guns held by arms (3D weapon handling): create {template:"fp_rifle", weapon:true | {attach:["vertical_grip"|"angled_grip"|"bipod"|"suppressor"], carry?}} (fp_pistol: weapon:true). weapon.grips names the grips (socket names or {part, at, look?, up?}): grip_main (default socket grip_r), grip_support (grip_l), stock, muzzle, optic (sight), mag; weapon.frames:{grip_main:{look, up}} = knuckle direction and back of the hand on each grip. Carry states (view space, about the trigger grip): hip, aim (optic on the eye line), ready_low, ready_high, sprint, reload (support hand on the magazine through the clip), holster | pistol: aim, compressed, low, reload, holster; states:{name:{base, rot:[x,y,z], at:[x,y,z], lock?, fire?}} adds your own. render {name:"arms", hold:{weapon:"ar", carry:"aim", clip?:"reload_empty", both?:true, fix?}} solves both arms onto the grips every frame (two-bone IK, wrist oriented to the grip, reach: support slides back then the gun moves back; dead zone: head / chest / shoulders, pushed forward then out; muzzle down outside firing states). render {name:"ar", hold:{arms:"arms", carry}} renders the gun carried the same way (layers line up). animate {name:"arms", clip, hold:{weapon:"ar", clip?, carry?, fps?, bake_weapon?:"<clip>"}} bakes a held arms clip (and the carried gun clip) for glTF export. check {name:"arms", hold:{weapon:"ar"}, clips?, carries?} validates every clip x carry state: hand-to-grip, reach, penetration, muzzle, on-screen share and arm occlusion.
- Arms that follow the gun: a 2D arm rig (art_rig) uses those anchors as per-frame IK targets: art_rig animate {name:"arms2d", animation:"reload", canvas:"arms_reload", ik_from:{canvas:"ar_reload", animation:"reload_empty", map:{hand_f:{anchor:"socket_grip_r", bend:-1}, hand_b:"socket_grip_l"}, offset?:[dx,dy]}, keys?}: same frame count and timing as the gun clip (give the arm rig the same frame size as the render, or offset:[dx,dy]), the hands land on the grips in every frame (map value "<anchor>" or {anchor, bend?, rot?:true (anchor rotation, + rot_offset) | deg, at?:[dx,dy], weight?}). End parts are your rig's hands: hand_f / hand_b on humanoid templates, or your own names (a minimal arms rig: frame = render size, root [80,119], body > upper_r > fore_r > hand_r and body > upper_l > fore_l > hand_l, see skill fp-weapon).
PRE-RENDERED FP WEAPON EXAMPLE: 1. create {name:"ar", template:"fp_rifle", textures:{..}} 2. render {name:"ar", canvas:"ar_reload", clip:"reload_empty", fps:12, size:[160,120], camera:"fp", hide:["magazine"], quantize:{colors:16, dither:true}, outline:"#14141a"} (gun layer) 3. render {name:"ar", canvas:"ar_reload_mag", clip:"reload_empty", fps:12, size:[160,120], camera:"fp", only:["magazine"]} (magazine layer, same anchors) 4. render {name:"ar", canvas:"ar_sway", sweep:{yaw:[-6,6,3], pitch:[-4,4,2]}, size:[160,120]} (sway / turn frames) 5. art_rig create a 2D arms rig with frame [160,120] and draw its parts, then animate {..., ik_from:{canvas:"ar_reload", animation:"reload_empty", map:{hand_r:"socket_grip_r", hand_l:"socket_grip_l"}}} 6. paint over any frame by hand, then art_animation export {canvas:"ar_reload", format:"spritesheet"} for each layer (json frames[].anchors line the layers up in-engine).
SKINNING (true skeletal deformation: mechs, exosuits, creatures, hoses, cables, flags, landing gear, 3D source characters for sprites):
- skeleton {name, skeleton:{template:"humanoid"|"exosuit"|"quadruped"|"chain"|"landing_gear", fit?:true (scale to the model height), height?, count?/from?/to? (chain)} | {from_parts:true} (bones = named rigid parts, joint = pivot) | {library:"<art_anim skeleton>", height?} (bones from the 2D rest pose: side view = depth, front = width) | {bones:{<name>:{parent?, head:[x,y,z] model px, tail?, rotate?, limits?:{x?|y?|z?:[min,max] deg}}}}, ik?:{<chain>:{bones:[root,..,end], pole?:[x,y,z]}}, constraints?:[{type:"aim"|"look_at"|"copy_rotation", bone, target:<bone>|[x,y,z]|<key target>, axis?, up?, from? (copy), weight?}], sockets?:{<name>:{bone, at, look?}}, cable?:{r, sides, texture, segments} (chain helper: a tube swept through the joints + heat weights)}. Humanoid / exosuit bones use the humanoid_hd names (pelvis torso chest neck head, upper_arm/forearm/hand_f|b, thigh/shin/foot_f|b; _f = right -X, _b = left +X; faces +Z), so 2D and 3D share clips. skeleton:null removes skeleton + skin.
- skin {name, skin:{method:"heat" (diffusion along bones, default) | "distance" (falloff?:6) | "rigid" (each part 100% to its bone: part bone:"x", rigid:{<part>:<bone>}, its name, else nearest; blend?:px = blended seams), parts?:[parts that get the method; others rigid], smooth?:2, exclude?:[bones], subdivide?:0..3, paint?:[{bone, weight, mode?:"set"|"add"|"smooth", region:{box|sphere:[x,y,z,r]|part|below|above|all} | canvas:<weight canvas> (luminance; view front|side|top)}], shapes?:{<name>:{sculpt:[{sphere|box|part, move?:[dx,dy,dz], inflate?:px, scale?}]} | {set:{<part>:{..}}} | {model}, driver?:{bone, axis:"x"|"y"|"z", from:0, to:90} (corrective: weight follows the joint angle)}}: <= 4 influences, normalised. weights {name, bone?} = weights_check (unweighted, > 4 before pruning, non-normalised) + heat map.
- pose {name, pose, bones:{<bone>:{rot, at, scale}}}; animate {name, clip, keys:[{t, bones|pose, morphs?:{<shape>:w}, ik?:{<chain>:{target:[x,y,z]|{bone, at}, weight?}}, targets?:{<name>:[x,y,z]}, ease?:linear|smooth|step|in|out}], loop?, events?, plant?:true|{chains, ground, threshold} (feet held on the ground by IK)} or animate {name, clip, retarget:{skeleton:"<art_anim skeleton>", clip?, map?:{<2D part>:<bone>}, scale?}} (2D side-view rotations -> rotations about X, root translation scaled by leg length). IK, plants, constraints and drivers are baked per frame.
- preview {name, clip|pose|bones, frames?, view?}; render {name, clip, sweep:{yaw:[0,315,45]}, quantize, outline} = 8-direction pixel sprites from one 3D body (socket anchors per frame).
- export: glTF skin (joints, inverseBindMatrices), JOINTS_0/WEIGHTS_0, shapes as morph targets on the skinned primitives, animations with TRS + weights channels, validated (structural). profile:"roblox" (max_bones?:50 assumed per MeshPart, r15?:true = R15 bone names): splits the mesh so each skin has <= max_bones joints, names [A-Za-z0-9_], morphs dropped. lods / bake_ao / impostor / atlas / instances are not available on skinned models yet.`;

Object.assign(TOPICS, AUDIO_TOPICS, PLANET_TOPICS);

TOPICS.graph = `ASSET GRAPH (art_graph): the light index of what is part of what
Orient yourself with it instead of calling art_info on every asset: replies are ids, relation types and one-line notes only (a few hundred chars).
Nodes: a bare name ("helmet_front": canvas, else model, rig, audio, group, project) or kind:name: canvas: rig: model: audio: project: group: palette: export:<path> file:<path>, and sub-assets layer:<canvas>/<layer>, anim:<canvas>/<tag>, frame:<canvas>/<n>, rigpart:<rig>/<part>, modelpart:<model>/<part>.
Automatic (derived from the workspace, never stale): project membership (part_of project:), layers (layer_of), animation tags (part_of), rig parts canvas + parts (part_of rig:), rig animate / model render outputs (rendered_from), model textures and placed models (depends_on), normal maps (variant_of {map:normal}), CTM tilesets (rendered_from), exports (exports_to export:<file>).
You add the semantic ones:
- link {from:"helmet_side", rel:"variant_of", to:"helmet_front", attrs:{view:"side"}}; rels: part_of variant_of view_of layer_of uses_palette rendered_from exports_to depends_on replaces, or a custom lowercase label. unlink {from, rel?, to?} or {node}.
- group {name:"Severance armour", members:["helmet_front","helmet_side"], parent?:"Armour", note?} (groups nest; cycles are refused); remove:[..]; delete:true.
- tag {node, add:["helmet"], remove?}; note {node, note:"one line"} (null clears).
Read:
- summary {} = workspace outline (groups tree, projects, tags); summary {group} = one group as a tree.
- query {node, depth?:1, rel?, dir?:"out"|"in"|"both", limit?:12} = adjacency list ("rel> target" outgoing, "<rel source" incoming, leaf sub-assets grouped on one line).
- find {tag|rel|text|kind} = matching nodes (rel alone lists those edges). path {from, to} = shortest relation chain.
Output is capped (max_chars, default 1600); narrow with rel, depth or limit. The web UI shows the graph live (Graph view).`;

export function helpText(a = {}) {
  if (a.op) {
    const u = opUsage(a.op);
    if (!u) throw new Error(`"${a.op}" is not a draw command (art_help {op} covers art_draw commands: ${Object.keys(SIGS).join(', ')}). Tool actions (e.g. art_rig animate) are in each tool's description and the guides: art_help {topic: ${Object.keys(TOPICS).join('|')}}.`);
    return u;
  }
  const t = a.topic || 'index';
  if (t === 'index') {
    return `Topics: ${Object.keys(TOPICS).join(', ')}. Ops: art_help {op:"name"} for: ${Object.keys(SIGS).join(', ')}.`;
  }
  if (t === 'ops') return Object.keys(SIGS).map(opUsage).join('\n\n');
  if (!TOPICS[t]) throw new Error(`Unknown topic "${t}". Topics: ${Object.keys(TOPICS).join(', ')}`);
  return TOPICS[t];
}
